#include <Geode/Geode.hpp>  using namespace geode::prelude;  // We hook into MenuLayer (the main menu) $modify(MenuLayer) {     bool init() {         // Run the original init first         if (!MenuLayer::init()) return false;          // Create the text label         // "worked" is the text, "goldFont.fnt" is the font style         auto label = CCLabelBMFont::create("worked", "goldFont.fnt");          // Position it (x, y)         // This puts it near the top center         auto winSize = CCDirector::sharedDirector()->getWinSize();         label->setPosition({ winSize.width / 2, winSize.height - 20 });                  // Scale it down a bit so it's not too huge         label->setScale(0.7f);          // Add it to the layer         this->addChild(label);          return true;     } };